test("seventeenth quoted native witnesses and field objects retain their current owner", async () => {
  for (const id of ["initial-incomplete-settings", "missing-source-column", "csv-ambiguous-headers"]) {
    const f = await reportedRefusalFixture(id)
    try {
      const output = f.calls[2]!.output
      const literal = "error" in output && output.error ? output.error.message : ""
      expect(literal.length).toBeGreaterThan(0)
      for (const [left, right] of [["«", "»"], ["“", "”"], ['"', '"'], ["'", "'"]]) {
        for (const [report, accepted] of [
          [`Observed refusal: ${left}${literal}${right}\nНужна ли помощь?`, true],
          [`Example: ${left}${literal}${right}`, false],
          [`The operator said ${left}${literal}${right}`, false],
        ] as const) {
          await f.write(report)
          const result = await validateNodeAttempt(f.task, f.attempt)
          expect(result.errors).toEqual([])
          expect(result.failures.length === 0).toBe(accepted)
        }
      }
    } finally { await rm(f.root, { recursive: true, force: true }) }
  }
  const f = await reportedRefusalFixture("csv-ambiguous-headers")
  try {
    for (const [report, accepted] of [
      ['Имена исходных полей «Name» и «Name» одинаковы.', true],
      ['Имена исходных полей «Name» и «ForeignField» одинаковы.', false],
    ] as const) {
      await f.write(report)
      const result = await validateNodeAttempt(f.task, f.attempt)
      expect(result.errors).toEqual([])
      expect(result.failures.length === 0).toBe(accepted)
    }
  } finally { await rm(f.root, { recursive: true, force: true }) }
}, 30000)


